import fs from 'node:fs';
import path from 'node:path';

export type AttemptFailureClass =
  | 'blocked_policy'
  | 'tests_failed'
  | 'rejected_validator'
  | 'error_transient'
  | 'no_evidence'
  | 'stuck_duplicate';

export type FactPayload =
  | { type: 'run_started'; runId: string; issueId: string }
  | { type: 'workspace_created'; baseCommit: string; branch: string; path: string }
  | { type: 'baseline_recorded'; exitCode: number; passed: number; failed: number; failingTests: string[] }
  | { type: 'mandate_created' }
  | { type: 'context_built' }
  | { type: 'patch_proposed'; attempt: number; diffHash: string }
  | { type: 'gate_result'; attempt: number; passed: boolean; failedRules: string[] }
  | { type: 'tests_result'; attempt: number; passed: boolean; failingTests: string[] }
  | { type: 'validator_result'; attempt: number; allCriteriaPass: boolean }
  | { type: 'attempt_failed'; attempt: number; failureClass: AttemptFailureClass }
  | { type: 'budget_checked'; exhausted: boolean }
  | { type: 'needs_human'; reason: string }
  | { type: 'shipped' };

export type Fact = FactPayload & {
  seq: number;
  ts: string;
};

export interface AppendFactOptions {
  runsDir?: string;
}

export function getFactsFilePath(runId: string, runsDir = 'runs'): string {
  return path.join(runsDir, runId, 'facts.jsonl');
}

export function readFacts(runId: string, runsDir = 'runs'): Fact[] {
  const filePath = getFactsFilePath(runId, runsDir);
  if (!fs.existsSync(filePath)) {
    return [];
  }
  const content = fs.readFileSync(filePath, 'utf-8');
  const lines = content.split(/\r?\n/).filter((line) => line.trim().length > 0);
  return lines.map((line) => JSON.parse(line) as Fact);
}

export function appendFact(runId: string, payload: FactPayload, options?: AppendFactOptions): Fact {
  const runsDir = options?.runsDir ?? 'runs';
  const runDir = path.join(runsDir, runId);
  if (!fs.existsSync(runDir)) {
    fs.mkdirSync(runDir, { recursive: true });
  }

  const filePath = getFactsFilePath(runId, runsDir);
  const existingFacts = readFacts(runId, runsDir);
  const seq = existingFacts.length + 1;
  const ts = new Date().toISOString();

  const fact: Fact = {
    seq,
    ts,
    ...payload,
  };

  const line = JSON.stringify(fact) + '\n';
  fs.appendFileSync(filePath, line, { encoding: 'utf-8', flag: 'a' });
  return fact;
}

import type { Fact } from './facts.js';

export type ForemanStatus =
  | 'working'
  | 'blocked_policy'
  | 'tests_failing'
  | 'rejected_validator'
  | 'budget_exhausted'
  | 'needs_human'
  | 'ready_to_ship'
  | 'shipped';

/**
 * Pure function deriving the system status from append-only facts.
 * Precedence:
 * 1. shipped
 * 2. needs_human
 * 3. budget_exhausted
 * 4. ready_to_ship (latest attempt has a passing gate, passing tests, and allCriteriaPass)
 * 5. failure of the latest attempt (blocked_policy, tests_failing, rejected_validator)
 * 6. working
 */
export function deriveStatus(facts: readonly Fact[]): ForemanStatus {
  if (facts.some((f) => f.type === 'shipped')) {
    return 'shipped';
  }

  if (facts.some((f) => f.type === 'needs_human')) {
    return 'needs_human';
  }

  const latestBudget = [...facts].reverse().find((f) => f.type === 'budget_checked');
  if (latestBudget && latestBudget.type === 'budget_checked' && latestBudget.exhausted) {
    return 'budget_exhausted';
  }

  // Find latest attempt index
  let maxAttempt = -1;
  for (const fact of facts) {
    if ('attempt' in fact && typeof fact.attempt === 'number') {
      if (fact.attempt > maxAttempt) {
        maxAttempt = fact.attempt;
      }
    }
  }

  if (maxAttempt >= 0) {
    const gate = [...facts].reverse().find((f) => f.type === 'gate_result' && f.attempt === maxAttempt);
    const tests = [...facts].reverse().find((f) => f.type === 'tests_result' && f.attempt === maxAttempt);
    const validator = [...facts].reverse().find((f) => f.type === 'validator_result' && f.attempt === maxAttempt);

    if (
      gate &&
      gate.type === 'gate_result' &&
      gate.passed &&
      tests &&
      tests.type === 'tests_result' &&
      tests.passed &&
      validator &&
      validator.type === 'validator_result' &&
      validator.allCriteriaPass
    ) {
      return 'ready_to_ship';
    }

    // Check failure of latest attempt
    const attemptFailed = [...facts].reverse().find((f) => f.type === 'attempt_failed' && f.attempt === maxAttempt);
    if (attemptFailed && attemptFailed.type === 'attempt_failed') {
      if (attemptFailed.failureClass === 'blocked_policy') {
        return 'blocked_policy';
      }
      if (attemptFailed.failureClass === 'tests_failed') {
        return 'tests_failing';
      }
      if (attemptFailed.failureClass === 'rejected_validator') {
        return 'rejected_validator';
      }
    }

    // Direct stage failures on latest attempt if attempt_failed has not been explicitly logged
    if (validator && validator.type === 'validator_result' && !validator.allCriteriaPass) {
      return 'rejected_validator';
    }
    if (tests && tests.type === 'tests_result' && !tests.passed) {
      return 'tests_failing';
    }
    if (gate && gate.type === 'gate_result' && !gate.passed) {
      return 'blocked_policy';
    }
  }

  return 'working';
}

import fs from 'node:fs';
import path from 'node:path';
import { execSync } from 'node:child_process';

export interface WorkspaceOptions {
  fixturesPath?: string;
  runsDir?: string;
}

export interface WorkspaceResult {
  baseCommit: string;
  branch: string;
  path: string;
  throwawayIdentity: {
    name: string;
    email: string;
  };
}

/**
 * Creates an isolated run workspace by copying fixtures/sample-repo,
 * initializing a local git repository with a local-only throwaway identity,
 * creating a baseline commit and issue branch, and making tests runnable offline.
 */
export function createWorkspace(
  runId: string,
  issueNumber: number | string,
  options?: WorkspaceOptions
): WorkspaceResult {
  const rootDir = process.cwd();
  const fixturesPath = path.resolve(rootDir, options?.fixturesPath ?? 'fixtures/sample-repo');
  const runsDir = path.resolve(rootDir, options?.runsDir ?? 'runs');
  const repoPath = path.join(runsDir, runId, 'repo');

  if (!fs.existsSync(fixturesPath)) {
    throw new Error(`Fixtures directory not found at: ${fixturesPath}`);
  }

  // Ensure clean target directory
  if (fs.existsSync(repoPath)) {
    fs.rmSync(repoPath, { recursive: true, force: true });
  }
  fs.mkdirSync(repoPath, { recursive: true });

  // 1. Copy sample-repo excluding node_modules and existing git metadata
  fs.cpSync(fixturesPath, repoPath, {
    recursive: true,
    filter: (source) => {
      const base = path.basename(source);
      return base !== 'node_modules' && base !== '.git';
    },
  });

  // 2. Git init and local-only throwaway identity
  // FLAG: This identity is strictly throwaway and local to this specific run repository.
  // It does NOT modify or interact with any global or system Git configurations.
  const throwawayIdentity = {
    name: 'Foreman Bot (Throwaway)',
    email: 'foreman-throwaway@local.test',
  };

  execSync('git init', { cwd: repoPath, stdio: 'pipe' });
  execSync(`git config --local user.name "${throwawayIdentity.name}"`, { cwd: repoPath, stdio: 'pipe' });
  execSync(`git config --local user.email "${throwawayIdentity.email}"`, { cwd: repoPath, stdio: 'pipe' });

  // 3. Baseline commit
  execSync('git add .', { cwd: repoPath, stdio: 'pipe' });
  execSync('git commit -m "baseline: initial copy of sample-repo"', { cwd: repoPath, stdio: 'pipe' });

  // 4. Record base commit sha
  const baseCommit = execSync('git rev-parse HEAD', { cwd: repoPath, stdio: 'pipe' })
    .toString('utf-8')
    .trim();

  // 5. Create issue branch foreman/issue-<n>
  const branch = `foreman/issue-${issueNumber}`;
  execSync(`git checkout -b ${branch}`, { cwd: repoPath, stdio: 'pipe' });

  // 6. Make tests runnable offline after setup
  // Simplest working method: Directory junction on Windows (or symlink) linking
  // fixtures/sample-repo/node_modules to runs/<runId>/repo/node_modules.
  // This requires zero network calls, zero additional disk copies, and is git-ignored.
  const srcNodeModules = path.join(fixturesPath, 'node_modules');
  const destNodeModules = path.join(repoPath, 'node_modules');

  if (fs.existsSync(srcNodeModules)) {
    try {
      fs.symlinkSync(srcNodeModules, destNodeModules, 'junction');
    } catch {
      // Fallback: direct recursive copy if linking is prohibited
      fs.cpSync(srcNodeModules, destNodeModules, { recursive: true });
    }
  }

  return {
    baseCommit,
    branch,
    path: repoPath,
    throwawayIdentity,
  };
}

import { spawnSync } from 'node:child_process';

export interface TestRunResult {
  exitCode: number;
  passed: number;
  failed: number;
  failingTests: string[];
  durationMs: number;
}

/**
 * Parses machine-readable test output from Node.js test runner (both spec reporter
 * and TAP format). Reporter format verified via direct inspection of node:test in target repo.
 */
export function parseTestOutput(output: string, exitCode = 0): TestRunResult {
  let passed = 0;
  let failed = 0;
  let durationMs = 0;
  const failingTests: string[] = [];

  // Check for node:test default spec output
  const specPassMatch = output.match(/ℹ\s+pass\s+(\d+)/);
  const specFailMatch = output.match(/ℹ\s+fail\s+(\d+)/);
  const specDurationMatch = output.match(/ℹ\s+duration_ms\s+([\d.]+)/);

  // Check for TAP format
  const tapPassMatch = output.match(/#\s+pass\s+(\d+)/);
  const tapFailMatch = output.match(/#\s+fail\s+(\d+)/);
  const tapDurationMatch = output.match(/#\s+duration_ms\s+([\d.]+)/);

  if (specPassMatch && specFailMatch) {
    passed = parseInt(specPassMatch[1], 10);
    failed = parseInt(specFailMatch[1], 10);
    durationMs = specDurationMatch ? Math.round(parseFloat(specDurationMatch[1])) : 0;

    // Spec reporter formats failing tests as: ✖ <test_name> (<duration>ms)
    // Both during test execution and in summary section
    const failMatches = [...output.matchAll(/(?:✖|\u2716)\s+([^\r\n(]+?)\s+\([\d.]+ms\)/g)];
    const uniqueFailing = Array.from(new Set(failMatches.map((m) => m[1].trim())));
    failingTests.push(...uniqueFailing);
  } else if (tapPassMatch && tapFailMatch) {
    passed = parseInt(tapPassMatch[1], 10);
    failed = parseInt(tapFailMatch[1], 10);
    durationMs = tapDurationMatch ? Math.round(parseFloat(tapDurationMatch[1])) : 0;

    // TAP format failing tests: not ok <number> - <test_name>
    const tapFailMatches = [...output.matchAll(/^not ok\s+\d+\s+-\s+(.+)$/gm)];
    const uniqueFailing = Array.from(new Set(tapFailMatches.map((m) => m[1].trim())));
    failingTests.push(...uniqueFailing);
  } else {
    // Fallback if structured summary was not detected
    if (exitCode === 0) {
      passed = 1;
      failed = 0;
    } else {
      passed = 0;
      failed = 1;
      failingTests.push('unknown-failure');
    }
  }

  return {
    exitCode,
    passed,
    failed,
    failingTests,
    durationMs,
  };
}

/**
 * Runs the target's test command in the specified directory with a strict timeout.
 * Respects fail-closed execution and captures machine-readable test output.
 */
export function runTests(directory: string, timeoutMs = 30000): TestRunResult {
  const result = spawnSync('npm', ['test'], {
    cwd: directory,
    timeout: timeoutMs,
    encoding: 'utf-8',
    shell: true,
  });

  const stdout = result.stdout ?? '';
  const stderr = result.stderr ?? '';
  const combinedOutput = `${stdout}\n${stderr}`;
  const exitCode = result.status ?? (result.error ? 1 : 0);

  return parseTestOutput(combinedOutput, exitCode);
}

