14: /**
15:  * Reads issues/issue-<n>.md from the Foreman repository root and parses it
16:  * into a structured Mandate object using deterministic markdown parsing.
17:  *
18:  * Rules:
19:  * - title: parsed from primary level 1 heading (# Issue <n>: <Title>)
20:  * - summary: parsed from ## Summary section
21:  * - acceptanceCriteria: parsed from ## Expected Behavior bullets or lines
22:  * - hintedPaths: parsed from file path patterns (e.g. src/*.ts)
23:  * - hintedSymbols: parsed from code-quoted identifiers / function invocations
24:  * - missing fields: assigned empty array or empty string, never left undefined
25:  */
26: export function loadMandate(issueId: string | number, issuesDir = 'issues'): Mandate {
27:   const normalizedId = String(issueId).replace(/^issue-/, '');
28:   const fileName = `issue-${normalizedId}.md`;
29:   const filePath = path.resolve(issuesDir, fileName);
30: 
31:   if (!fs.existsSync(filePath)) {
32:     throw new Error(`Issue specification file not found: ${filePath}`);
33:   }
34: 
35:   const content = fs.readFileSync(filePath, 'utf-8');
36: 
37:   // 1. Title extraction
38:   const titleMatch = content.match(/^#\s+(?:Issue\s+\d+:\s*)?(.*)$/m);
39:   const title = titleMatch ? titleMatch[1].trim() : '';
40: 
41:   // 2. Summary extraction
42:   const summaryMatch = content.match(/##\s+Summary\s*([\s\S]*?)(?=\n##\s+|$)/);
43:   const summary = summaryMatch ? summaryMatch[1].trim() : '';
44: 
45:   // 3. Acceptance criteria from ## Expected Behavior
46:   const expectedMatch = content.match(/##\s+Expected Behavior\s*([\s\S]*?)(?=\n##\s+|$)/);
47:   const acceptanceCriteria: string[] = [];
48:   if (expectedMatch) {
49:     const rawLines = expectedMatch[1]
50:       .split(/\r?\n/)
51:       .map((l) => l.trim())
52:       .filter(Boolean);
53:     const bullets = rawLines
54:       .filter((l) => l.startsWith('- ') || l.startsWith('* '))
55:       .map((l) => l.slice(2).trim());
