import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface LedgerEntry {
  ts: string;
  runId: string;
  model: string;
  promptTokens: number;
  completionTokens: number;
  /** null when the price for this model is not configured */
  estimatedCostUsd: number | null;
}

interface PriceConfig {
  input_per_1k: number | null;
  output_per_1k: number | null;
}

interface PricesFile {
  [model: string]: PriceConfig;
}

// ---------------------------------------------------------------------------
// Step-level caps (enforced per run, not per call)
// ---------------------------------------------------------------------------

export const STEP_MAX_COMPLETION_TOKENS_PER_CALL = 4000;
export const STEP_MAX_TOTAL_TOKENS = 60000;
export const STEP_MAX_PATCH_ATTEMPTS = 1;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function loadPrices(): PricesFile {
  const pricesPath = path.resolve(__dirname, 'prices.json');
  const raw = fs.readFileSync(pricesPath, 'utf-8');
  return JSON.parse(raw) as PricesFile;
}

function getLedgerPath(runsDir = 'runs'): string {
  return path.resolve(runsDir, 'ledger.jsonl');
}

function readLedger(ledgerPath: string): LedgerEntry[] {
  if (!fs.existsSync(ledgerPath)) return [];
  const content = fs.readFileSync(ledgerPath, 'utf-8');
  return content
    .split(/\r?\n/)
    .filter((l) => l.trim().length > 0)
    .map((l) => JSON.parse(l) as LedgerEntry);
}

function estimateCost(
  model: string,
  promptTokens: number,
  completionTokens: number,
  prices: PricesFile,
): number | null {
  const entry = prices[model];
  if (!entry) return null;
  if (entry.input_per_1k === null || entry.output_per_1k === null) return null;
  return (promptTokens / 1000) * entry.input_per_1k +
    (completionTokens / 1000) * entry.output_per_1k;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Checks whether the model's price is configured (non-null).
 * Throws if the price entry is missing or null.
 */
export function assertPriceConfigured(model: string): void {
  const prices = loadPrices();
  const entry = prices[model];
  if (!entry) {
    throw new Error(
      `Ledger: no price entry for model "${model}". Add it to src/model/prices.json before making model calls.`,
    );
  }
  if (entry.input_per_1k === null || entry.output_per_1k === null) {
    throw new Error(
      `Ledger: price for model "${model}" is null in prices.json. ` +
        `Fill in input_per_1k and output_per_1k from the provider's published list prices before running.`,
    );
  }
}

/**
 * Returns the cumulative estimated cost from the ledger.
 * Entries with null cost (unknown price) are counted as zero toward the cap
 * but are still recorded for token tracking.
 */
export function cumulativeCost(runsDir = 'runs'): number {
  const entries = readLedger(getLedgerPath(runsDir));
  return entries.reduce((sum, e) => sum + (e.estimatedCostUsd ?? 0), 0);
}

/**
 * Returns the cumulative total tokens across all entries.
 */
export function cumulativeTokens(runsDir = 'runs'): { prompt: number; completion: number; total: number } {
  const entries = readLedger(getLedgerPath(runsDir));
  const prompt = entries.reduce((s, e) => s + e.promptTokens, 0);
  const completion = entries.reduce((s, e) => s + e.completionTokens, 0);
  return { prompt, completion, total: prompt + completion };
}

/**
 * Records a model call and enforces the budget cap.
 *
 * Throws if:
 *  - the model's price is null in prices.json (because we cannot enforce the cap)
 *  - the running estimated total already exceeds FOREMAN_BUDGET_USD
 *
 * Always appends the entry (even when cost is null, for token tracking).
 * The cap refusal happens BEFORE appending.
 */
export function recordModelCall(opts: {
  runId: string;
  model: string;
  promptTokens: number;
  completionTokens: number;
  runsDir?: string;
}): LedgerEntry {
  const { runId, model, promptTokens, completionTokens, runsDir = 'runs' } = opts;

  const prices = loadPrices();

  // Refuse if price is null — we cannot enforce the cap
  assertPriceConfigured(model);

  const budgetUsd = parseFloat(process.env.FOREMAN_BUDGET_USD ?? '8');
  const existingCost = cumulativeCost(runsDir);
  if (existingCost >= budgetUsd) {
    throw new Error(
      `Ledger: budget cap exceeded. Running total $${existingCost.toFixed(4)} >= cap $${budgetUsd.toFixed(2)}. Set FOREMAN_BUDGET_USD to increase.`,
    );
  }

  const estimatedCostUsd = estimateCost(model, promptTokens, completionTokens, prices);

  const entry: LedgerEntry = {
    ts: new Date().toISOString(),
    runId,
    model,
    promptTokens,
    completionTokens,
    estimatedCostUsd,
  };

  const ledgerPath = getLedgerPath(runsDir);
  const dir = path.dirname(ledgerPath);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  fs.appendFileSync(ledgerPath, JSON.stringify(entry) + '\n', 'utf-8');

  return entry;
}

