132: export function validateRubricEvidence(
133:   criteria: readonly RubricCriterion[],
134:   issueText: string,
135:   context: RubricValidityContext
136: ): EvidenceValidation {
137:   const valid: RubricCriterion[] = [];
138:   const invalid: { id: string; reason: string }[] = [];
139:   const testNames = new Set(context.knownTestNames);
140:   const symbols = new Set(context.knownSymbols);
141:   const issue = normalize(issueText);
142: 
143:   for (const criterion of criteria) {
144:     const ref = criterion.evidence_ref;
145:     if (!ref || !ref.value || !ref.value.trim()) {
146:       invalid.push({ id: criterion.id, reason: 'evidence_ref is missing a value' });
147:       continue;
148:     }
149:     const value = ref.value.trim();
150:     if (ref.kind === 'test') {
151:       if (testNames.has(value)) valid.push(criterion);
152:       else invalid.push({ id: criterion.id, reason: `evidence_ref test "${value}" was not found in the test files` });
153:     } else if (ref.kind === 'symbol') {
154:       if (symbols.has(value)) valid.push(criterion);
155:       else invalid.push({ id: criterion.id, reason: `evidence_ref symbol "${value}" is not in context.json` });
156:     } else if (ref.kind === 'issue_text') {
157:       if (issue.includes(normalize(value))) valid.push(criterion);
158:       else invalid.push({ id: criterion.id, reason: `evidence_ref issue_text "${value}" is not a substring of the issue text` });
159:     } else {
160:       invalid.push({ id: criterion.id, reason: `evidence_ref kind "${String(ref.kind)}" is not test|symbol|issue_text` });
161:     }
162:   }
163:   return { valid, invalid };
164: }
