166: function walkFiles(dir: string): string[] {
167:   const out: string[] = [];
168:   if (!fs.existsSync(dir)) return out;
169:   for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
170:     if (entry.name === 'node_modules' || entry.name === '.git') continue;
171:     const full = path.join(dir, entry.name);
172:     if (entry.isDirectory()) out.push(...walkFiles(full));
173:     else out.push(full);
174:   }
175:   return out;
