180:   const root = path.resolve(repoPath);
181:   const names = new Set<string>();
182:   const pattern = /(?:^|\s)(?:test|it)\s*\(\s*['"`]([^'"`]+)['"`]/g;
183:   for (const file of walkFiles(path.join(root, 'test'))) {
184:     let content: string;
185:     try {
