278: 
279:   for (let attempt = 1; attempt <= 2; attempt++) {
280:     const messages: ChatMessage[] =
281:       attempt === 1
282:         ? baseMessages
283:         : [
284:             ...baseMessages,
285:             {
286:               role: 'user',
287:               content:
288:                 'Your previous output was invalid. Errors:\n- ' +
289:                 lastErrors.join('\n- ') +
290:                 '\nReturn corrected JSON only. Each criterion must include a valid evidence_ref.',
