422: /**
423:  * Line-ending tolerance.
424:  *
425:  * The patch model emits LF newlines, but a checkout on a host with
426:  * core.autocrlf=true can materialise CRLF files (this happened: the run copy's
427:  * files were CRLF after `git reset --hard`, so multi-line LF search strings
428:  * failed to match). We match on an LF-normalised view and restore the file's
429:  * original ending style, so an LF search matches a CRLF file and vice versa.
430:  */
431: function toLf(text: string): string {
432:   return text.replace(/\r\n/g, '\n');
433: }
434: 
435: function restoreLineEndings(text: string, crlf: boolean): string {
436:   const lf = toLf(text);
437:   return crlf ? lf.replace(/\n/g, '\r\n') : lf;
438: }
439: 
440: /**
441:  * Applies edits to the run copy. Every search string must occur exactly once in
442:  * its file; otherwise the attempt fails and NOTHING is written. Validates all
443:  * edits against in-memory content first, then writes all files.
444:  */
445: export function applyEdits(repoPath: string, edits: PatchEdit[]): ApplyResult {
446:   const root = path.resolve(repoPath);
447:   const contents = new Map<string, string>();
448:   const applied: { file: string; replacedChars: number }[] = [];
449: 
450:   for (let index = 0; index < edits.length; index++) {
451:     const edit = edits[index];
452:     const fullPath = path.resolve(repoPath, edit.file);
453: 
454:     if (fullPath !== root && !fullPath.startsWith(root + path.sep)) {
455:       return { ok: false, reason: `path escapes repo: ${edit.file}`, index, file: edit.file };
456:     }
457: 
458:     let current = contents.get(fullPath);
459:     if (current === undefined) {
460:       if (!fs.existsSync(fullPath)) {
461:         return { ok: false, reason: `file not found: ${edit.file}`, index, file: edit.file };
462:       }
463:       current = fs.readFileSync(fullPath, 'utf-8');
464:     }
465: 
466:     // Match on an LF-normalised view so the model's LF output applies to a file
467:     // that the run copy materialised as CRLF (or vice versa).
468:     const usesCrlf = current.includes('\r\n');
469:     const haystack = toLf(current);
470:     const needle = toLf(edit.search);
471: 
472:     const occurrences = countOccurrences(haystack, needle);
473:     if (occurrences === 0) {
474:       return { ok: false, reason: `search string not found in ${edit.file}`, index, file: edit.file };
475:     }
476:     if (occurrences > 1) {
477:       return {
478:         ok: false,
479:         reason: `search string occurs ${occurrences} times in ${edit.file} (must be exactly once)`,
480:         index,
481:         file: edit.file,
482:       };
483:     }
484: 
485:     const replaced = haystack.replace(needle, toLf(edit.replace));
486:     contents.set(fullPath, restoreLineEndings(replaced, usesCrlf));
487:     applied.push({ file: edit.file, replacedChars: edit.search.length });
488:   }
489: 
490:   for (const [fullPath, text] of contents) {
491:     fs.writeFileSync(fullPath, text, 'utf-8');
492:   }
493: 
494:   return { ok: true, applied };
495: }
